      if (amount <= 0) {
        throw new Error("Withdrawal must be positive");
      }

      if (amount > balance) {
        throw new Error("Insufficient balance");
      }

      balance -= amount;
      return balance;
    },

    getBalance() {
      return balance;
    }
  };
}
