```javascript
function throttle(fn, interval) {
  let throttled = false;

  return function throttledFunction(...args) {
    if (throttled) {
      return;
    }

    throttled = true;
    fn.apply(this, args);

    setTimeout(() => {
      throttled = false;
    }, interval);
  };
}
```

